mapper.select:
select temp_data.*,
tmpTable.hasFlow
from(

    /*流程中*/

    SELECT
    #{PAGE_DATE_STATUS03} statusValid,

    tpd.WORKFLOW_ID workflowId
    from
    WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tpd

    where

    tpd.PS=#{PS_T12}

    and tpd.TRADE_STATUS = #{TRADE_STATUS01}
    and tpd.IS_CANCEL = #{YESNO_N}

    UNION ALL

    SELECT
    #{PAGE_DATE_STATUS03} statusValid,

    tpd.WORKFLOW_ID workflowId
    from
    WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tpd

    where

    tpd.PS=#{PS_T13}

    and tpd.TRADE_STATUS = #{TRADE_STATUS01}
    and tpd.IS_CANCEL = #{YESNO_N}

    UNION ALL

    SELECT
    #{PAGE_DATE_STATUS03} statusValid,

    tpd.WORKFLOW_ID workflowId
    from
    WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tpd

    where

    tpd.PS=#{PS_T11}

    and tpd.TRADE_STATUS = #{TRADE_STATUS01}
    and tpd.IS_CANCEL = #{YESNO_N}





        UNION ALL

    SELECT
    #{PAGE_DATE_STATUS05} statusValid,

    null workflowId
    from
    TRD_FIN_PRODUCT_DEAL_TOTAL  tpd

    where
    tpd.PS=#{PS_T12}
    and tpd.TRADE_STATUS = #{TRADE_STATUS01}
    and tpd.IS_CANCEL = #{YESNO_N}

    UNION ALL

    SELECT
    #{PAGE_DATE_STATUS05} statusValid,

    null workflowId
    from
    TRD_FIN_PRODUCT_DEAL_TOTAL tpd

    where

    tpd.PS=#{PS_T13}

    and tpd.TRADE_STATUS = #{TRADE_STATUS01}
    and tpd.IS_CANCEL = #{YESNO_N}

    UNION ALL

    SELECT
    #{PAGE_DATE_STATUS05} statusValid,

    null workflowId
    from
    TRD_FIN_PRODUCT_DEAL_TOTAL tpd

    where

    tpd.PS=#{PS_T11}

    and tpd.TRADE_STATUS = #{TRADE_STATUS01}
    and tpd.IS_CANCEL = #{YESNO_N}


/*撤销数据*/


        UNION ALL

    SELECT
    #{PAGE_DATE_STATUS06} statusValid,

    null workflowId
    FROM
    TRD_FIN_PRODUCT_DEAL_TOTAL  tpd

    where
    tpd.PS=#{PS_T12}
    and tpd.TRADE_STATUS = #{TRADE_STATUS03}
    and tpd.IS_CANCEL = #{YESNO_N}

