    SELECT
    #{PAGE_DATE_STATUS06} statusValid,

    null workflowId
    from
    TRD_FIN_PRODUCT_DEAL_TOTAL tpd

    where

    tpd.PS=#{PS_T13}

    and tpd.TRADE_STATUS = #{TRADE_STATUS03}
    and tpd.IS_CANCEL = #{YESNO_N}

    UNION ALL

    SELECT
    #{PAGE_DATE_STATUS06} statusValid,

    null workflowId
    from
    TRD_FIN_PRODUCT_DEAL_TOTAL tpd

    where

    tpd.PS=#{PS_T11}

    and tpd.TRADE_STATUS = #{TRADE_STATUS03}
    and tpd.IS_CANCEL = #{YESNO_N}


) temp_data
left join (
select distinct B_TRADE_ID,hasFlow from (
SELECT B_TRADE_ID,'01' hasFlow FROM TRD_FIN_PRODUCT_DEAL_TOTAL total where total.B_TRADE_ID is not null
and total.TRADE_STATUS = #{TRADE_STATUS01}
and total.FINPROD_TYPE2 = #{finprodTypeTg}
and total.IS_CANCEL = #{YESNO_N}
UNION all
SELECT B_TRADE_ID,'01' hasFlow FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL total where total.B_TRADE_ID is not null
and total.TRADE_STATUS = #{TRADE_STATUS01}
and total.FINPROD_TYPE2 = #{finprodTypeTg}
and total.IS_CANCEL = #{YESNO_N}) zz
) tmpTable on tmpTable.B_TRADE_ID = temp_data.TOTLE_TRADE_ID
order by temp_data.registDate desc

SELECT
psp.AMOUNT registShare
from PTL_SEC_POSITION psp
left join FIN_PRODUCT fp on psp.FINPROD_ID = fp.FINPROD_ID
where
psp.PORTFOLIO_ID = #{portfolioId}
and psp.CDATE = STR_TO_DATE(#{registDate},'%Y-%m-%d')
and fp.FINPROD_MARKET_ID = #{finprodMarketId}
and psp.HODING_TYPE = #{HOLDING_TYPE_03}

choose.when:
select psp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, psp.AMOUNT registShare,
pp.INVEST_YESORNO investYesorno,
psp.CDATE registDate from PTL_SEC_POSITION psp inner join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID inner join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = psp.PORTFOLIO_ID where IFNULL(pp.PARENT_PORTFOLIO_ID,'null') = 'null' and psp.CDATE = #{registDate,jdbcType=DATE}
AND PSP.SEC_ACCT_ID = #{chlId}
AND PSP.SEC_ACCT_ID = '999999'
and psp.AMOUNT >0
and fp.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
and fp.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and psp.HODING_TYPE = #{POSITION_TYPE03} order by AMOUNT
